import React from 'react';
import Icon from './Icon';

function InfoPage({ title, subtitle, sections, onBack }) {
  return (
    <div style={{ minHeight: '80vh', padding: '28px 18px', color: '#e2e8f0' }}>
      <button
        type="button"
        className="btn mb-4 fw-bold text-white border-0"
        style={{
          background: 'linear-gradient(135deg, #7c3aed 0%, #a855f7 100%)',
          boxShadow: '0 18px 30px rgba(124, 58, 237, 0.30)',
        }}
        onClick={onBack}
      >
        ⬅ Quay lại
      </button>

      <div
        className="card p-4 shadow-sm border-0"
        style={{
          background: 'rgba(15, 23, 42, 0.96)',
          border: '1px solid rgba(79, 70, 229, 0.18)',
          maxWidth: 960,
          margin: '0 auto',
          borderRadius: 22,
        }}
      >
        <div style={{ display: 'flex', alignItems: 'center', gap: 14, marginBottom: 20 }}>
          <div
            style={{
              width: 48,
              height: 48,
              display: 'grid',
              placeItems: 'center',
              borderRadius: '50%',
              background: 'linear-gradient(135deg, #7c3aed 0%, #ec4899 100%)',
              boxShadow: '0 18px 30px rgba(124, 58, 237, 0.25)',
            }}
          >
            <Icon name="play" size={20} className="text-white" />
          </div>
          <div>
            <h2 className="fw-bold mb-1" style={{ color: '#c4b5fd' }}>{title}</h2>
            <p style={{ color: '#94a3b8', margin: 0 }}>{subtitle}</p>
          </div>
        </div>

        {sections.map((section) => (
          <div key={section.heading} style={{ marginBottom: 22 }}>
            <h3 style={{ color: '#e2e8f0', marginBottom: 10 }}>{section.heading}</h3>
            <p style={{ color: '#cbd5e1', lineHeight: 1.8 }}>{section.text}</p>
          </div>
        ))}
      </div>
    </div>
  );
}

export default InfoPage;
